arguments.command:
cat > tests/forms_test.sh <<'EOF'
#!/bin/bash
fail=0
bash bin/render event | grep -q 'action=' || { echo "render"; fail=1; }
bash bin/handle POST '/events/1/edit?action=save' | grep -q '^200 save' || { echo "handle"; fail=1; }
# Function URL only allows A-Z a-z 0-9 _ . - in query keys (docs/platform/cirrus-functions.md)
for f in event seat refund; do
  bash bin/render "$f" | grep -o 'action="[^"]*"' | grep -q '?[^"=]*[^A-Za-z0-9_.=&-][^"=]*=' && { echo "bad query key in $f"; fail=1; }
done
bash bin/handle POST '/events/1/edit?/save' | grep -q '^404' || { echo "legacy"; fail=1; }
exit $fail
EOF
bash tests/forms_test.sh; echo rc=$?
cat > lib/actions.sh <<'EOF'
#!/bin/bash
# Form actions: a form posts to its own page with the action named in the query (?action=name).
# The query key must use only A-Z a-z 0-9 _ . - (Function URL rejects others, e.g. "?/name").
action_url() { echo "?action=$1"; }
# Prints the action named by a query string, or nothing.
action_from_query() { case "$1" in action=*) echo "${1#action=}" ;; esac; }
EOF
sed -i 's|`?/<操作名>`|`?action=<操作名>`|' docs/framework.md
bash scripts/verify.sh; echo rc=$?; bash bin/render refund

